import math

def kl_divergence(p, q, eps=1e-9):
    return sum(pi * math.log((pi + eps) / (qi + eps)) for pi, qi in zip(p, q))

def hybrid_similarity(geodesic_dist: float, p, q, alpha=0.7):
    kl = kl_divergence(p, q)
    return 1.0 / (1.0 + alpha * geodesic_dist + (1 - alpha) * kl)

export function safeLogRatio(p: number, q: number, eps = 1e-9): number {
  return Math.log((p + eps) / (q + eps))
}

export function bounded(value: number, lo = -1e6, hi = 1e6): number {
  return Math.max(lo, Math.min(hi, value))
}
